// Read every selected body before analysis. Long materials are digested in full, in bounded batches.
import {requestAI} from './v08-ai.mjs';
const cache=new Map(),encoder=new TextEncoder();
export async function eventBody(event){if(cache.has(event.id))return cache.get(event.id);const promise=(async()=>{const r=await fetch('/api/news/body?eventId='+encodeURIComponent(event.id));const d=await r.json();if(!r.ok||d.coverage!=='full-text'||!d.body)throw Error(d.error||'正文暂时不可读取');return d;})();cache.set(event.id,promise);try{return await promise;}catch(e){cache.delete(event.id);throw e;}}
export function splitBody(material,limit=24000){
 const text=String(material.text),out=[];let start=0;while(start<text.length){let lo=start,hi=text.length;while(lo<hi){const mid=Math.ceil((lo+hi)/2);if(encoder.encode(text.slice(start,mid)).length<=limit)lo=mid;else hi=mid-1;}let end=lo;if(end<text.length){const p=text.lastIndexOf('\n',end);if(p>start+(end-start)*.5)end=p+1;}if(end<=start)throw Error('正文分段失败');out.push({...material,id:material.id+'#part'+(out.length+1),text:text.slice(start,end)});start=end;}return out;
}
export function materialBatches(materials,limit=100000){const batches=[];let current=[],bytes=0;for(const m of materials){const n=encoder.encode(m.text).length;if(n>limit)throw Error('正文分段超过请求限制');if(current.length&&(bytes+n>limit||current.length>=28)){batches.push(current);current=[];bytes=0;}current.push(m);bytes+=n;}if(current.length)batches.push(current);return batches;}
export async function analyzeEvents({events,cfg,task,question='',context=null,progress=()=>{}}){
 const selected=events.slice(0,context?29:30),materials=[];if(!selected.length)throw Error('请选择需要分析的事件');for(const [i,e]of selected.entries()){progress(`正在读取正文 ${i+1}/${selected.length}，完成后可在我的资料库查看。`);let x;try{x=await eventBody(e);}catch(err){throw Error('“'+e.title+'”正文读取失败。请打开原文，或取消勾选后重试。');}materials.push({id:e.id,text:[e.date,e.title,'正文：',x.body].join('\n'),date:e.date,url:e.url,locator:'全文 · '+x.contentHash.slice(0,12)});}
 const all=context?[...materials,context]:materials,bytes=all.reduce((s,x)=>s+encoder.encode(x.text).length,0);if(bytes<=110000&&all.every(x=>x.text.length<=30000)){progress('正在分析正文，完成后可在我的资料库查看。');return {result:await requestAI(cfg,task,all,question),materials:all};}
 const chunks=materials.flatMap(x=>splitBody(x)),batches=materialBatches(chunks),digests=new Map(materials.map(m=>[m.id,[]]));
 for(const [i,batch]of batches.entries()){progress(`正在整理正文 ${i+1}/${batches.length}，完成后可在我的资料库查看。`);const r=await requestAI(cfg,'news_digest',batch,question);for(const point of r.points){for(const part of point.sourceIds){const id=part.replace(/#part\d+$/,'');if(digests.has(id))digests.get(id).push((point.heading?point.heading+'：':'')+point.text);}}if(batch.some(x=>!r.points.some(p=>p.sourceIds.includes(x.id))))throw Error('部分正文分段未被模型整理，请减少选择后重试');}
 const condensed=materials.map(m=>({...m,text:[m.date,m.text.split('\n')[1],'基于逐段完整正文提取：',...[...new Set(digests.get(m.id))]].join('\n'),locator:'全文分段整理 · '+m.locator}));if(context)condensed.push(context);if(condensed.reduce((s,x)=>s+encoder.encode(x.text).length,0)>110000||condensed.some(x=>x.text.length>30000))throw Error('逐段整理结果较多，请分组选择事件后分析');progress('正在生成整体解读，完成后可在我的资料库查看。');return {result:await requestAI(cfg,task,condensed,question),materials:condensed};
}
